param([Parameter(Mandatory)][string]$ManifestFile,[Parameter(Mandatory)][string]$HostManifestPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedHostManifestKeyId,[Parameter(Mandatory)][string]$SupervisorConfigurationPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedSupervisorConfigurationKeyId,[Parameter(Mandatory)][string]$ReleaseSigningPublicKeyFile,[switch]$AllowTestManifest)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";$file=[IO.Path]::GetFullPath($ManifestFile);$bytes=[IO.File]::ReadAllBytes($file);Test-BackupSignature $bytes ([IO.File]::ReadAllBytes("$file.sig")) $HostManifestPublicKeyFile 'Service host manifest';$m=[Text.Encoding]::UTF8.GetString($bytes)|ConvertFrom-Json -Depth 15 -DateKind String;if($m.Product-cne'ET.Server'-or$m.ArtifactType-cne'WindowsServiceHostManifest'-or([bool]$m.TestOnly-and-not$AllowTestManifest)){throw 'Windows service host manifest is invalid or test-only'};$hostFingerprint=Get-BackupKeyFingerprint $HostManifestPublicKeyFile 'Service host manifest' $false;$supervisor=Get-BackupKeyFingerprint $SupervisorConfigurationPublicKeyFile 'Supervisor configuration' $false;$release=Get-BackupKeyFingerprint $ReleaseSigningPublicKeyFile 'Release signer' $false;if(@(@($hostFingerprint,$supervisor,$release)|Select-Object -Unique).Count-ne3-or$m.HostManifestKeyId-cne$ExpectedHostManifestKeyId-or$m.SupervisorConfigurationKeyId-cne$ExpectedSupervisorConfigurationKeyId-or$m.HostManifestPublicKeySha256-cne$hostFingerprint-or$m.SupervisorConfigurationPublicKeySha256-cne$supervisor-or$m.ReleaseSigningPublicKeySha256-cne$release){throw 'Windows service host trust identity is invalid'};foreach($name in @('WinSw','PowerShell','Launcher','SupervisorConfiguration','SupervisorConfigurationSignature','ServiceXml')){$path=[string]$m.Files.$name;$hash=[string]$m.Files.("${name}Sha256");if(-not(Test-Path $path -PathType Leaf)-or(Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()-cne$hash){throw "Windows service host component changed: $name"}};if($m.Files.WinSwSha256-cne$m.ExpectedWinSwSha256){throw 'WinSW approval hash mismatch'};$xml=[xml](Get-Content $m.Files.ServiceXml -Raw);if($xml.service.id-cne$m.ServiceId-or$xml.service.serviceaccount.username-cne$m.ServiceAccount-or$xml.service.startmode-cne'Automatic'-or$xml.service.delayedAutoStart-cne'true'-or$xml.service.stoptimeout-cne'60 sec'-or$xml.service.preshutdownTimeout-cne'3 min'-or$xml.service.resetfailure-cne'1 hour'-or$xml.service.env){throw 'Windows service XML policy is invalid'};$failures=@($xml.service.onfailure);if($failures.Count-ne3-or$failures[0].action-cne'restart'-or$failures[0].delay-cne'10 sec'-or$failures[1].action-cne'restart'-or$failures[1].delay-cne'30 sec'-or$failures[2].action-cne'none'){throw 'Windows service failure recovery policy is invalid'};[ordered]@{Passed=$true;ServiceId=$m.ServiceId;ServiceAccount=$m.ServiceAccount;AutomaticDelayedStart=$true;GracefulStopSeconds=60;FailureActions=@('restart-10s','restart-30s','none');ManifestSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json
